css_path = Path("app/styles/app.css")
css = css_path.read_text()
css += '''\n\n/* Collapsible local-rule settings */\n.local-rules-disclosure {\n  min-width: 0;\n}\n\n.local-rules-disclosure > summary {\n  display: grid;\n  min-width: 0;\n  min-height: 48px;\n  grid-template-columns: minmax(0, 1fr) auto auto;\n  align-items: center;\n  gap: 12px;\n  border-radius: 12px;\n  cursor: pointer;\n  list-style: none;\n  padding: 4px 2px;\n}\n\n.local-rules-disclosure > summary::-webkit-details-marker {\n  display: none;\n}\n\n.local-rules-disclosure > summary:hover,\n.local-rules-disclosure > summary:focus-visible {\n  color: var(--green);\n}\n\n.local-rules-summary-title {\n  font-size: 0.82rem;\n  font-weight: 800;\n}\n\n.local-rules-summary-status {\n  min-width: 0;\n  color: var(--muted);\n  font-size: 0.74rem;\n  font-weight: 750;\n  white-space: nowrap;\n}\n\n.local-rules-summary-chevron {\n  color: var(--muted);\n  font-size: 1.35rem;\n  line-height: 1;\n  transition: transform 160ms ease;\n}\n\n.local-rules-disclosure[open] > summary .local-rules-summary-chevron {\n  transform: rotate(90deg);\n}\n\n.local-rules-disclosure-body {\n  display: grid;\n  gap: 12px;\n  margin-top: 10px;\n  border-top: 1px solid var(--line);\n  padding-top: 14px;\n}\n\n.local-rules-description {\n  margin: 0;\n  color: var(--muted);\n  font-size: 0.74rem;\n  line-height: 1.55;\n}\n\n.admin-local-rules .local-rules-disclosure-summary h2,\n.admin-local-rules .local-rules-disclosure-summary p {\n  margin: 0;\n}\n\n.admin-local-rules .local-rules-disclosure-summary h2 {\n  margin-top: 4px;\n  font-size: 1.1rem;\n}\n\n.admin-local-rules .local-rules-disclosure-body > .button {\n  justify-self: end;\n}\n\n@media (max-width: 520px) {\n  .local-rules-disclosure > summary {\n    grid-template-columns: minmax(0, 1fr) auto;\n    gap: 4px 10px;\n  }\n\n  .local-rules-summary-status {\n    grid-column: 1;\n    grid-row: 2;\n    overflow: hidden;\n    text-overflow: ellipsis;\n  }\n\n  .local-rules-summary-chevron {\n    grid-column: 2;\n    grid-row: 1 / span 2;\n  }\n}\n'''
